"""Neighbourhood and FAQ pages approved from the SEO drafts.

Generated by build.py. Copy rules: write "Tri-Cities, BC" (never bare "Tri-Cities"),
and do not use "best", "top", or a William Chen review.
"""
import html as _html
import json
import re

from partials import (
    BROKERAGE_ADDR, CALC, EMAIL, ICONS, PHONE, TEL,
    foot, head, picture,
)

I = ICONS

_BARE_TRI = re.compile(r"Tri-Cities(?!\s*,\s*BC)")
_SUPER = re.compile(r"\b(?:best|top)\b", re.I)
_WILLIAM = re.compile(r"William\s+Chen", re.I)


def assert_copy(text, label):
    bare = _BARE_TRI.search(text)
    if bare:
        start = max(0, bare.start() - 40)
        raise SystemExit(f"{label}: bare Tri-Cities near {text[start:bare.end() + 20]!r}")
    hit = _SUPER.search(text)
    if hit:
        start = max(0, hit.start() - 40)
        raise SystemExit(f"{label}: forbidden word {hit.group(0)!r} near {text[start:hit.end() + 20]!r}")
    if _WILLIAM.search(text):
        raise SystemExit(f"{label}: William Chen review")


def _plain(fragment):
    return re.sub(r"\s+", " ", _html.unescape(re.sub(r"<[^>]+>", "", fragment))).strip()


def page_nav(items):
    links = "".join(f'<a href="#{anchor}">{label}</a>' for anchor, label in items)
    return f'<nav class="page-nav" aria-label="On this page"><div class="container"><span class="pn-label">On this page</span>{links}</div></nav>'


def faq_jsonld(items):
    entities = []
    for item in items:
        question, answer = item[0], item[1]
        text = item[2] if len(item) > 2 else _plain(answer)
        entities.append({
            "@type": "Question",
            "name": _plain(question),
            "acceptedAnswer": {"@type": "Answer", "text": text},
        })
    return '<script type="application/ld+json">\n' + json.dumps({
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": entities,
    }, indent=2, ensure_ascii=False) + "\n</script>"


def _portrait():
    return f'''<figure class="portrait guide-photo">
      {picture("assets/img/devin-headshot", (480, 800), 800, 1000, "Devin Desaulniers, Real Estate Associate with Axford Real Estate", "headshot", eager="auto", sizes_attr="(max-width: 899px) 70vw, 280px")}
      <figcaption><strong>Devin Desaulniers</strong><span>Real Estate Associate · Axford Real Estate</span></figcaption>
    </figure>'''


def _section(anchor, eyebrow, heading, inner, paper=False):
    klass = "section section--paper" if paper else "section"
    return f'''<section class="{klass}" id="{anchor}">
  <div class="container narrow-wide">
    <span class="eyebrow">{eyebrow}</span>
    <h2>{heading}</h2>
    {inner}
  </div>
</section>'''


def _faq_block(heading, items):
    rows = "".join(f'<div class="faq-item"><h3>{q}</h3><div class="ans">{a}</div></div>' for q, a, *_ in items)
    return f'''<section class="section section--paper" id="faq">
  <div class="container">
    <div class="sec-head sec-head--center"><div><span class="eyebrow">FAQ</span><h2>{heading}</h2></div></div>
    <div class="faq-list">{rows}</div>
  </div>
</section>'''


def _sources(note, rows):
    items = "".join(
        f'<li><a href="{_html.escape(url, quote=True)}" target="_blank" rel="noopener">{title}</a> <span class="src-meta">· {meta}</span></li>'
        for title, url, meta in rows
    )
    return f'''<section class="section" id="sources">
  <div class="container narrow-wide">
    <section class="post-sources" aria-labelledby="sources-h">
      <h2 id="sources-h">Sources</h2>
      <p>{note}</p>
      <ol>{items}</ol>
    </section>
  </div>
</section>'''


def _cta(heading, text, buttons):
    return f'''<section class="section section--night cta-band">
  <div class="container center narrow">
    <h2>{heading}</h2>
    <p>{text}</p>
    <div class="btn-row">{buttons}</div>
  </div>
</section>'''


def _phone_row():
    return (
        f'<a class="btn btn-ghost-light" href="{TEL}">{I["phone"]} Call or text {PHONE}</a>'
        f'<a class="btn btn-ghost-light" href="mailto:{EMAIL}">Email Devin</a>'
    )


def _ext(url, label):
    return f'<a href="{_html.escape(url, quote=True)}" target="_blank" rel="noopener">{label}</a>'


def _page(filename, title, desc, eyebrow, h1, lead, nav, intro_lead, intro_rest, body, faq_heading, faq_items, cta_html, sources_html):
    html = head(title, desc, "area-guide", page_url=filename, extra_head=faq_jsonld(faq_items))
    html += f'''
<section class="page-hero">
  <div class="container">
    <span class="eyebrow">{eyebrow}</span>
    <h1>{h1}</h1>
    <p class="lead">{lead}</p>
    <div class="btn-row">
      <a class="btn btn-light" href="#faq">Common questions {I["arrow"]}</a>
      <a class="btn btn-ghost-light" href="{TEL}">{I["phone"]} Call or text {PHONE}</a>
    </div>
  </div>
</section>
{page_nav(nav)}
<article class="guide">
<section class="section">
  <div class="container guide-intro">
    <div>
      <p class="lead guide-lead">{intro_lead}</p>
      {intro_rest}
    </div>
    {_portrait()}
  </div>
</section>
{body}
{_faq_block(faq_heading, faq_items)}
{sources_html}
</article>
{cta_html}
'''
    html += foot()
    assert_copy(html, filename)
    return filename, html


